mapper.update:
UPDATE sys_imp_tmp
SET pass_count = #{passCount}
  , fail_count = #{failCount}
  , chk_rslt = #{chkRslt}
  , chk_dscr = #{chkDscr}
  , result_json = #{resultJson}
  , updt_time = #{updtTime}
WHERE imp_id = #{impId}
  AND is_deleted = 0

UPDATE sys_imp_tmp
SET save_rslt = #{saveRslt}
  , save_dscr = #{saveDscr}
  , result_json = #{resultJson}
  , updt_time = #{updtTime}
WHERE imp_id = #{impId}
  AND is_deleted = 0

UPDATE sys_imp_tmp_detl
SET chk_rslt = #{chkRslt}
  , chk_dscr = #{chkDscr}
  , fld002 = #{fld002}
  , fld003 = #{fld003}
  , fld005 = #{fld005}
  , fld006 = #{fld006}
  , fld007 = #{fld007}
  , fld008 = #{fld008}
  , fld009 = #{fld009}
  , fld010 = #{fld010}
  , fld011 = #{fld011}
  , updt_time = #{updtTime}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE sys_imp_tmp_detl
SET save_rslt = #{saveRslt}
  , save_dscr = #{saveDscr}
  , ref_id = #{refId}
  , updt_time = #{updtTime}
WHERE id = #{id}
  AND is_deleted = 0

mapper.select:
SELECT COUNT(1)
FROM sys_imp_tmp_detl
WHERE imp_id = #{impId}
  AND is_deleted = 0
  AND chk_rslt = #{chkRslt}
